import type { Metadata } from "next";
import { Caveat_Brush } from "next/font/google";
import localFont from "next/font/local";

// The landing page is the only indexable page (#277), so it alone names the
// canonical URL. Its client page cannot export metadata, hence this layout. It
// must not set openGraph: a deeper segment's openGraph replaces the root one,
// including the image generated by app/opengraph-image.tsx.
export const metadata: Metadata = {
  alternates: { canonical: "/" },
};

// #603 (docs/decisions/2026-11-28-landing-billet-doux.md): the landing sets
// Fraunces optical sizes per element, so it needs the opsz axis. A second
// Fraunces instance with the axis is served under its own family: adding the
// axis to the root instance would change every other page's headings. Google
// Fonts' Fraunces v38, ital,opsz,wght@9..144,300..600 (OFL, see
// app/fonts/fraunces-OFL.txt); the 100..900 build next/font downloads drops the "e" crossbar
// at opsz 96. Body and label text use the root Figtree and Jost (app/fonts.ts).
// Caveat Brush is the felt-pen note on the "Tu gardes la main" sheet, and
// nothing else; its next/font/google build renders with correct widths (#607).
const landingDisplay = localFont({
  variable: "--font-landing-display",
  src: [
    { path: "../fonts/fraunces-opsz-latin.woff2", weight: "300 600", style: "normal" },
    { path: "../fonts/fraunces-opsz-italic-latin.woff2", weight: "300 600", style: "italic" },
  ],
  display: "swap",
});
const hand = Caveat_Brush({ variable: "--font-landing-hand", subsets: ["latin"], weight: "400", display: "swap" });

export default function LandingLayout({ children }: Readonly<{ children: React.ReactNode }>) {
  return <div className={`${landingDisplay.variable} ${hand.variable}`}>{children}</div>;
}
